import pandas as pd
import numpy as np

def quality_counts_fixed(df: pd.DataFrame) -> dict:
    missing = (df["reading"].isna() | df["baseline"].isna()).sum()
    undefined = ((df["reading"] == 0) & (df["baseline"] == 0)).sum()
    return {"missing": int(missing), "undefined_ratio": int(undefined)}

df = pd.DataFrame({
    "reading": pd.Series([0, 1, np.nan, 2], dtype="Float64"),
    "baseline": pd.Series([0, 2, 1, 4], dtype="Float64")
})

print(f"DF:\n{df}")
result = quality_counts_fixed(df)
print(f"Result: {result}")

expected = {"missing": 1, "undefined_ratio": 1}
if result == expected:
    print("SUCCESS")
else:
    print(f"FAILURE: Expected {expected}, got {result}")
EOF
